export function memoize(fn) {
  const cache = new Map();
  return (key) => {
    if (!cache.has(key)) {
      const pending = Promise.resolve(fn(key));
      pending.catch(() => cache.delete(key));
      cache.set(key, pending);
    }
    return cache.get(key);
  };
}

