import test from "node:test";
import assert from "node:assert/strict";

import { memoize } from "../src/memo.js";

test("one lookup for two concurrent callers", async () => {
  let calls = 0;
  const slow = memoize(async (key) => {
    calls += 1;
    await new Promise((resolve) => setTimeout(resolve, 5));
    return key + "-value";
  });
  const [left, right] = await Promise.all([slow("k"), slow("k")]);
  assert.equal(left, "k-value");
  assert.equal(right, "k-value");
  assert.equal(calls, 1);
});

